-- Installed native special sublimations: fpR.ax exact rarity and independent fpI.ahB slot.
-- EPIC uses native fof.RELIC2 code7; RELIC uses native fof.RELIC code5.
-- ExportNativeSublimations / ExportNativeSublimationTargets; installed aLO bdata.
-- Target export SHA256: a971a671554540209bdaec862fe54a7177baaecf5acc0750cd3c653b99c7669d
ALTER TABLE native_sublimation_patterns DROP CONSTRAINT native_sublimation_patterns_slot_colors_check;
ALTER TABLE native_sublimation_patterns ADD CONSTRAINT native_sublimation_pattern_colors CHECK ((pattern_type='BASIC' AND cardinality(slot_colors) BETWEEN 1 AND 4) OR (pattern_type IN ('EPIC','RELIC') AND cardinality(slot_colors)=0));
CREATE TABLE native_sublimation_targets (
 reference integer PRIMARY KEY CHECK(reference>0),
 item_level integer NOT NULL CHECK(item_level>=0),
 pattern_type text NOT NULL CHECK(pattern_type IN ('EPIC','RELIC')),
 rarity_code smallint NOT NULL,
 enabled boolean NOT NULL DEFAULT TRUE,
 client_jar_sha256 char(64) NOT NULL CHECK(client_jar_sha256 ~ '^[0-9a-f]{64}$'),
 CHECK ((pattern_type='EPIC' AND rarity_code=7) OR (pattern_type='RELIC' AND rarity_code=5))
);
